import React,{useEffect,useMemo,useState}from'react';
import{createRoot}from'react-dom/client';
import{BrowserRouter,useLocation,useNavigate,useParams}from'react-router-dom';
import*as I from'lucide-react';
import{cats,products,starterPriceOffers,starterSaleRequests,starterTraderPrices,starterTraders}from'./data';
import'./styles.css';

const number=n=>new Intl.NumberFormat('ar-EG').format(n);
const readStore=(key,fallback)=>{try{const value=localStorage.getItem(key);return value?JSON.parse(value):fallback}catch{return fallback}};
function useStored(key,fallback){const[value,setValue]=useState(()=>readStore(key,fallback));useEffect(()=>localStorage.setItem(key,JSON.stringify(value)),[key,value]);return[value,setValue]}
function Logo(){return <div className="logo" aria-label="كوكب كراكيب"><img src="/logo.svg" alt=""/><span>كوكب <b>كراكيب</b></span></div>}
const requestState={review:['قيد مراجعة المالك','review'],assigned:['أُسند إلى تاجر','assigned'],contacted:['بانتظار اتفاق التاجر','contacted'],completed:['اكتمل البيع','completed'],rejected:['يحتاج تعديل','rejected']};
function Status({value}){const[label,kind]=requestState[value]||requestState.review;return <span className={'statusPill '+kind}><i></i>{label}</span>}
function Stars({rating}){return <span className="stars"><I.Star fill="currentColor"/> {Number(rating).toFixed(1)}</span>}

function App(){
  const nav=useNavigate();const{pathname}=useLocation();
  const[dark,setDark]=useState(localStorage.dark==='1');
  const[toast,setToast]=useState('');
  const[traders,setTraders]=useStored('kawkap_traders',starterTraders);
  const[requests,setRequests]=useStored('kawkap_sale_requests',starterSaleRequests);
  const[priceOffers,setPriceOffers]=useStored('kawkap_price_offers',starterPriceOffers);
  const[traderPrices,setTraderPrices]=useStored('kawkap_trader_prices',starterTraderPrices);
  const[notifications,setNotifications]=useStored('kawkap_notifications',[{id:'notice-owner-start',audience:'owner',title:'طلبات بيع تحتاج مراجعتك',body:'توجد طلبات بانتظار قرارك وإسنادها إلى تاجر مناسب.',time:'الآن',read:false,type:'request'}]);
  const[clientCount,setClientCount]=useStored('kawkap_client_count',12840);
  const[currentUser,setCurrentUser]=useStored('kawkap_current_user',null);
  const[installPrompt,setInstallPrompt]=useState(null);
  useEffect(()=>{document.documentElement.classList.toggle('dark',dark);localStorage.dark=dark?'1':'0'},[dark]);
  useEffect(()=>{const capture=e=>{e.preventDefault();setInstallPrompt(e)};const installed=()=>{setInstallPrompt(null);notify('تم تثبيت كوكب كراكيب كتطبيق على جهازك')};window.addEventListener('beforeinstallprompt',capture);window.addEventListener('appinstalled',installed);return()=>{window.removeEventListener('beforeinstallprompt',capture);window.removeEventListener('appinstalled',installed)}},[]);
  const notify=text=>{setToast(text);window.clearTimeout(window.kawkapToast);window.kawkapToast=window.setTimeout(()=>setToast(''),3200)};
  const activeAudience=sessionStorage.getItem('kawkap_owner')==='active'?'owner':currentUser?.role==='trader'?'trader':'client';
  const visibleNotifications=notifications.filter(n=>n.audience==='all'||n.audience===activeAudience||n.audience==='trader'&&n.traderId===currentUser?.traderId);
  const pushNotifications=list=>setNotifications(prev=>[...list.map(n=>({id:`notice-${Date.now()}-${Math.random().toString(16).slice(2)}`,time:'الآن',read:false,...n})),...prev]);
  const requestNotificationPermission=async()=>{if(!('Notification'in window)){notify('إشعارات الجهاز غير مدعومة في هذا المتصفح');return}const permission=await Notification.requestPermission();if(permission==='granted'){notify('تم تفعيل إشعارات الجهاز لهذا الحساب');try{new Notification('كوكب كراكيب',{body:'سيصلك تنبيه عند حدوث تحديث جديد.'})}catch{}}else notify('يمكنك تفعيل الإشعارات لاحقًا من إعدادات المتصفح')};
  const installApp=async()=>{if(installPrompt){installPrompt.prompt();const result=await installPrompt.userChoice;if(result.outcome==='accepted')notify('يجري تثبيت التطبيق على جهازك');setInstallPrompt(null)}else notify('لتثبيت التطبيق: افتح قائمة المتصفح ثم اختر «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية».')};
  const createRequest=data=>{const id=`S-${String(Date.now()).slice(-5)}`;setRequests(prev=>[{...data,id,status:'review',traderId:null,createdAt:'منذ لحظات'},...prev]);pushNotifications([{audience:'owner',type:'request',title:'طلب بيع جديد يحتاج مراجعة',body:`${data.title} — ${data.category} في ${data.location}`},{audience:'client',type:'request',title:'تم استلام طلب البيع',body:'وصل طلبك إلى المالك وسيتم إشعارك عند الموافقة والإسناد.'}]);notify('تم إرسال طلب البيع إلى مالك الموقع للمراجعة والإسناد');return id};
  const register=({role,data})=>{
    if(role==='client'){setClientCount(v=>v+1);setCurrentUser({role:'client'});pushNotifications([{audience:'client',type:'welcome',title:'أهلًا بك في كوكب كراكيب',body:'تم تسجيلك بخصوصية. يمكنك الآن إرسال طلب بيع.'},{audience:'owner',type:'client',title:'عميل جديد في العداد',body:'تم تحديث عداد العملاء من دون إظهار أي بيانات شخصية.'}]);notify('تم تسجيلك كعميل بنجاح. خصوصيتك محفوظة.');return}
    const id=`tr-${Date.now()}`;const trader={id,name:data.name,initial:data.name.trim().charAt(0)||'ت',rating:0,reviews:0,specialty:data.specialty,city:data.city,status:'pending',verified:false,reply:'بانتظار اعتماد المالك'};
    setTraders(prev=>[trader,...prev]);setCurrentUser({role:'trader',traderId:id});pushNotifications([{audience:'owner',type:'trader',title:'طلب تسجيل تاجر جديد',body:`${data.name} بانتظار الاعتماد في سجل التجار.`},{audience:'trader',traderId:id,type:'trader',title:'تم استلام تسجيلك كتاجر',body:'سيُتاح لك المتجر المصغّر بعد اعتماد مالك الموقع.'}]);notify('تم تسجيل طلب التاجر وسيظهر لمالك الموقع لاعتماده');
  };
  const assignRequest=(requestId,traderId)=>{const trader=traders.find(t=>t.id===traderId);const request=requests.find(r=>r.id===requestId);if(!trader){notify('اختر تاجرًا نشطًا أولًا');return}setRequests(prev=>prev.map(r=>r.id===requestId?{...r,status:'assigned',traderId}:r));pushNotifications([{audience:'client',type:'approved',title:'وافق المالك على طلب البيع',body:`تم توجيه طلب «${request?.title||''}» إلى ${trader.name}.`},{audience:'trader',traderId,type:'assignment',title:'تم إسناد طلب بيع جديد إليك',body:`الطلب «${request?.title||''}» جاهز لتضع عرض شراءك.`},{audience:'owner',type:'assignment',title:'تم إسناد الطلب بنجاح',body:`تم توجيه ${request?.id||'الطلب'} إلى ${trader.name}.`}]);notify(`تمت إحالة الطلب إلى ${trader.name}`)};
  const savePriceOffer=data=>{setPriceOffers(prev=>{const old=prev.find(o=>o.requestId===data.requestId&&o.traderId===data.traderId);return old?prev.map(o=>o.id===old.id?{...o,...data,updatedAt:'الآن'}:o):[{...data,id:`offer-${Date.now()}`,updatedAt:'الآن'},...prev]});const req=requests.find(r=>r.id===data.requestId);pushNotifications([{audience:'client',type:'price',title:'وصل عرض شراء من التاجر',body:`قدّم التاجر سعر ${number(data.amount)} ج.م / ${data.unit} لطلب «${req?.title||''}».`},{audience:'owner',type:'price',title:'تاجر أضاف أو عدّل سعرًا',body:`تم تحديث عرض الشراء للطلب ${data.requestId}.`}]);notify('تم حفظ سعر الشراء وإرسال إشعار للأطراف المعنية')};
  const saveTraderPrice=data=>setTraderPrices(prev=>data.id?prev.map(p=>p.id===data.id?{...p,...data}:p):[{...data,id:`price-${Date.now()}`},...prev]);
  const rateTrader=(traderId,rating)=>{setTraders(prev=>prev.map(t=>t.id===traderId?{...t,rating:((t.rating*t.reviews+rating)/(t.reviews+1)).toFixed(1),reviews:t.reviews+1}:t));pushNotifications([{audience:'trader',traderId,type:'rating',title:'وصل تقييم جديد لمتجرك',body:`قام عميل بإضافة تقييم ${rating} من ٥.`}]);notify('شكرًا لتقييمك، تم حفظه للتاجر')};
  const addTrader=data=>{const id=`tr-${Date.now()}`;setTraders(prev=>[{id,name:data.name,initial:data.name.charAt(0)||'ت',specialty:data.specialty,city:data.city,rating:Number(data.rating)||0,reviews:0,status:'active',verified:true,reply:'تاجر مضاف من المالك'},...prev]);pushNotifications([{audience:'owner',type:'trader',title:'تمت إضافة تاجر يدويًا',body:`تم اعتماد ${data.name} وإضافته إلى الدليل.`}]);notify('تمت إضافة التاجر واعتماده')};
  const markAllRead=()=>setNotifications(prev=>prev.map(n=>visibleNotifications.some(v=>v.id===n.id)?{...n,read:true}:n));
  const adminProps={traders,setTraders,requests,assignRequest,clientCount,addTrader,requestNotificationPermission,onLogout:()=>{sessionStorage.removeItem('kawkap_owner');notify('تم تسجيل الخروج بأمان')}};
  let page;
  if(pathname==='/')page=<Home go={nav} clientCount={clientCount} traders={traders}/>;
  else if(pathname==='/market')page=<Marketplace go={nav} requests={requests} traders={traders}/>;
  else if(pathname.startsWith('/request/'))page=<RequestDetail go={nav} requests={requests} traders={traders} priceOffers={priceOffers} currentUser={currentUser}/>;
  else if(pathname==='/sell')page=<Sell go={nav} createRequest={createRequest}/>;
  else if(pathname==='/orders'||pathname==='/cart')page=<SaleRequests go={nav} requests={requests} traders={traders} priceOffers={priceOffers}/>;
  else if(pathname==='/traders')page=<Traders go={nav} traders={traders} rateTrader={rateTrader}/>;
  else if(pathname==='/chat')page=<Chat go={nav} traders={traders}/>;
  else if(pathname==='/register')page=<Registration go={nav} register={register} requestNotificationPermission={requestNotificationPermission}/>;
  else if(pathname==='/trader-login'||pathname==='/trader')page=<TraderAccess go={nav} traders={traders} currentUser={currentUser} setCurrentUser={setCurrentUser} requests={requests} priceOffers={priceOffers} traderPrices={traderPrices} savePriceOffer={savePriceOffer} saveTraderPrice={saveTraderPrice} requestNotificationPermission={requestNotificationPermission}/>;
  else if(pathname==='/notifications')page=<NotificationsPage go={nav} notifications={visibleNotifications} audience={activeAudience} markAllRead={markAllRead} requestNotificationPermission={requestNotificationPermission}/>;
  else if(pathname==='/profile')page=<Profile go={nav} clientCount={clientCount} currentUser={currentUser}/>;
  else if(pathname==='/owner-login'||pathname==='/admin')page=<OwnerAccess {...adminProps}/>;
  else if(pathname==='/about')page=<About/>;
  else page=<Home go={nav} clientCount={clientCount} traders={traders}/>;
  const unread=visibleNotifications.filter(n=>!n.read).length;
  return <><Header go={nav} dark={dark} setDark={setDark} unread={unread} onInstall={installApp}/><main>{page}</main><Bottom go={nav} path={pathname}/>{toast&&<div className="toast"><I.CircleCheck/> {toast}</div>}</>;
}
function Header({go,dark,setDark,unread,onInstall}){return <header><div className="top"><button className="icon menuButton" aria-label="القائمة"><I.Menu/></button><button className="logoButton" onClick={()=>go('/')}><Logo/></button><button className="headsearch" onClick={()=>go('/market')}><I.Search/><span>ابحث في فرص البيع والتجار...</span><kbd>استكشاف</kbd></button><button className="icon themeButton" onClick={()=>setDark(!dark)} aria-label="تبديل المظهر">{dark?<I.Sun/>:<I.Moon/>}</button><button className="installEntry" onClick={onInstall} title="تثبيت كوكب كراكيب كتطبيق"><I.Download/><span>تثبيت التطبيق</span></button><button className={'icon notificationButton '+(unread?'hasUnread':'')} onClick={()=>go('/notifications')} aria-label="الإشعارات"><I.Bell/>{unread>0&&<em>{unread>9?'٩+':number(unread)}</em>}</button><button className="registerEntry" onClick={()=>go('/register')}><I.UserPlus/><span>تسجيل خارجي</span></button><button className="traderEntry" onClick={()=>go('/trader-login')}><I.Store/><span>بوابة التاجر</span></button><button className="ownerEntry" onClick={()=>go('/owner-login')}><I.LockKeyhole/><span>دخول المالك</span></button></div></header>}
function Bottom({go,path}){const links=[[I.House,'الرئيسية','/'],[I.Send,'أرسل للبيع','/sell'],[I.Store,'التجار','/traders'],[I.MessageCircle,'المحادثات','/chat'],[I.UserRound,'حسابي','/profile']];return <nav className="bottom">{links.map(([C,label,to])=><button className={path===to?'active':''} onClick={()=>go(to)} key={to}><span><C/></span>{label}</button>)}</nav>}

function Home({go,clientCount,traders}){const active=traders.filter(t=>t.status==='active');return <>
  <section className="hero wrap sellHero"><div className="heroText"><span className="eyebrow"><I.ShieldCheck/> عملية بيع بإشراف المنصة</span><h1>حوّل كراكيبك<br/>إلى <mark>قيمة</mark></h1><p>أرسل ما تريد بيعه، ودع مالك كوكب كراكيب يراجعه ويُحيله إلى التاجر المتخصص المناسب. لا بيع مباشر ولا خطوة بلا موافقة.</p><div className="actions"><button className="primary" onClick={()=>go('/sell')}>أرسل طلب بيع <I.ArrowLeft/></button><button className="secondary" onClick={()=>go('/traders')}>تعرّف على التجار</button></div><div className="trust"><span><b>+{number(clientCount)}</b> عميل مسجّل بخصوصية</span><span><b>{number(active.length)}</b> تاجر موثوق ونشط</span><span><b>٤ خطوات</b> حتى عرض التاجر</span></div></div><div className="heroVisual"><div className="planet"><img src="/logo.svg" alt="شعار كوكب كراكيب"/><span className="orbit one"><I.FileCheck/></span><span className="orbit two"><I.Store/></span><span className="orbit three"><I.MessageCircle/></span></div><div className="floatCard"><I.Route/><div><b>المسار تحت السيطرة</b><small>مراجعة ثم إسناد ثم تواصل آمن</small></div></div></div></section>
  <section className="wrap workflowSection"><div className="sectionTitle"><div><small>مسار بسيط وواضح</small><h2>كيف تبيع كراكيبك؟</h2></div><span className="processNote"><I.LockKeyhole/> المالك يوافق ويختار التاجر</span></div><div className="workflow">{[[I.Send,'١. أرسل طلب البيع','أدخل نوع الكراكيب والكمية والمنطقة دون نشر بياناتك الشخصية.'],[I.ClipboardCheck,'٢. مراجعة المالك','يراجع مالك الموقع الطلب قبل بدء أي عملية.'],[I.UserRoundCog,'٣. إسناد لتاجر مناسب','المالك وحده يختار التاجر حسب التخصص والمنطقة والتقييم.'],[I.MessagesSquare,'٤. دردشة وعرض','تتواصل مع التاجر المُسند، ثم تقيّم تجربتك بعد الإتمام.']].map(([C,title,text])=><article key={title}><span><C/></span><h3>{title}</h3><p>{text}</p></article>)}</div></section>
  <section className="wrap section traderPreview"><Title over="اختيارات موثقة" title="تجار بتقييمات حقيقية" action={()=>go('/traders')}/><div className="traderGrid">{active.slice(0,3).map(t=><TraderCard trader={t} key={t.id} go={go}/>)}</div></section>
  <section className="rescue wrap"><div><span className="eyebrow light"><I.EyeOff/> خصوصية العميل أولًا</span><h2>بيانات العميل لا تظهر للعامة</h2><p>عداد العملاء يعرض العدد فقط. أما تفاصيل طلب البيع فتظل لدى المنصة وتُشارك بالقدر اللازم مع التاجر الذي اختاره المالك.</p><button onClick={()=>go('/register')}>سجّل بالطريقة المناسبة <I.ArrowLeft/></button></div><div className="ecoStats"><span><I.UsersRound/><b>{number(clientCount)}</b><small>عميل مسجّل</small></span><span><I.BadgeCheck/><b>{number(active.length)}</b><small>تاجر موثوق</small></span><span><I.ShieldCheck/><b>١٠٠٪</b><small>إشراف قبل البدء</small></span></div></section>
</>}
function Title({over,title,action}){return <div className="sectionTitle"><div><small>{over}</small><h2>{title}</h2></div>{action&&<button onClick={action}>عرض الكل <I.ArrowLeft/></button>}</div>}

function TraderCard({trader,go,admin=false,onActivate,onSuspend}){return <article className={'traderCard '+(trader.status!=='active'?'pendingTrader':'')}><div className="traderTop"><span className="traderAvatar">{trader.initial}</span><div><h3>{trader.name}{trader.verified&&<I.BadgeCheck/>}</h3><p><I.MapPin/> {trader.city}</p></div><StatusTrader value={trader.status}/></div><div className="traderFacts"><span><I.BriefcaseBusiness/><small>التخصص</small><b>{trader.specialty}</b></span><span><I.Star/><small>التقييم</small><b>{trader.reviews?`${Number(trader.rating).toFixed(1)} / ٥`:'جديد'}</b></span><span><I.MessageCircle/><small>الاستجابة</small><b>{trader.reply}</b></span></div>{admin?<div className="traderAdminActions">{trader.status==='pending'&&<button className="primary" onClick={()=>onActivate(trader.id)}><I.Check/> اعتماد التاجر</button>}{trader.status==='active'&&<button className="secondary warning" onClick={()=>onSuspend(trader.id)}><I.PauseCircle/> إيقاف مؤقت</button>}{trader.status==='suspended'&&<button className="secondary" onClick={()=>onActivate(trader.id)}><I.RotateCcw/> إعادة التفعيل</button>}</div>:<div className="traderCardFoot"><Stars rating={trader.rating}/><span>{number(trader.reviews)} تقييم</span><button onClick={()=>go('/sell')} disabled={trader.status!=='active'}><I.Route/> اطلب إحالة</button></div>}</article>}
function StatusTrader({value}){const labels={active:'موثّق',pending:'بانتظار الاعتماد',suspended:'موقوف مؤقتًا'};return <span className={'traderStatus '+value}>{labels[value]||value}</span>}

function Marketplace({go,requests,traders}){const[search,setSearch]=useState('');const[category,setCategory]=useState('');const list=useMemo(()=>requests.filter(r=>r.status==='assigned').filter(r=>(!category||r.category===category)&&(!search||r.title.includes(search)||r.category.includes(search)||r.location.includes(search))),[requests,search,category]);return <section className="wrap page"><div className="pageHead"><div><small>الفرص التي مرت بمراجعة المنصة</small><h1>فرص بيع مُسندة</h1><p>طلبات اختار لها المالك تاجرًا متخصصًا؛ لا توجد عملية بيع مباشرة خارج الإشراف.</p></div><button className="primary" onClick={()=>go('/sell')}><I.Send/> أرسل طلب بيع</button></div><div className="marketSearch"><I.Search/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="ابحث بالنوع أو المنطقة..."/><button onClick={()=>setSearch('')}><I.X/> مسح</button></div><div className="chips"><button className={!category?'active':''} onClick={()=>setCategory('')}>الكل</button>{cats.slice(0,7).map(c=><button className={category===c[0]?'active':''} onClick={()=>setCategory(c[0])} key={c[0]}>{c[0]}</button>)}</div><div className="resultbar"><b>{number(list.length)} فرصة معتمدة</b><span className="ownerRule"><I.ShieldCheck/> تُسند للتاجر من لوحة المالك فقط</span></div>{list.length?<div className="requestGrid">{list.map(r=><RequestCard request={r} trader={traders.find(t=>t.id===r.traderId)} go={go} key={r.id}/>)}</div>:<Empty go={go}/>}</section>}
function RequestCard({request,trader,go}){return <article className="requestCard"><div className="requestImage"><img src={request.image||products[0].img} alt=""/><Status value={request.status}/></div><div className="requestBody"><small>{request.category}</small><h3>{request.title}</h3><p><I.Scale/> {request.quantity} <span><I.MapPin/> {request.location}</span></p>{trader?<div className="assignedTrader"><span className="mini">{trader.initial}</span><div><small>التاجر الذي أسنده المالك</small><b>{trader.name} {trader.verified&&<I.BadgeCheck/>}</b></div><Stars rating={trader.rating}/></div>:<div className="awaiting"><I.Clock3/> بانتظار إسناد المالك</div>}<button onClick={()=>go('/request/'+request.id)}>عرض التفاصيل <I.ArrowUpLeft/></button></div></article>}
function Empty({go}){return <div className="empty"><I.SearchX/><h2>لا توجد فرص مطابقة الآن</h2><p>يمكنك إرسال طلب بيع جديد وسيراجعه مالك الموقع.</p><button className="primary" onClick={()=>go('/sell')}>أرسل طلب بيع</button></div>}
function RequestDetail({go,requests,traders,priceOffers,currentUser}){const{id}=useParams();const request=requests.find(r=>r.id===id);if(!request)return <Empty go={go}/>;const trader=traders.find(t=>t.id===request.traderId);const offer=priceOffers.find(o=>o.requestId===request.id&&o.traderId===request.traderId);const isAssignedTrader=currentUser?.role==='trader'&&currentUser.traderId===request.traderId;const isOwner=sessionStorage.getItem('kawkap_owner')==='active';const canViewContact=isAssignedTrader||isOwner;return <section className="wrap page requestDetail"><button className="backLink" onClick={()=>go('/market')}><I.ArrowRight/> العودة لفرص البيع</button><div className="requestDetailGrid"><div className="detailImage"><img src={request.image||products[0].img} alt=""/></div><div className="requestDetailInfo"><Status value={request.status}/><small>{request.id} · {request.category}</small><h1>{request.title}</h1><p>هذا طلب بيع يمر عبر كوكب كراكيب. لا يبدأ أي اتفاق إلا بعد مراجعة المالك وتوجيه الطلب إلى تاجر مناسب.</p><div className="detailFacts"><span><I.Scale/><small>الكمية</small><b>{request.quantity}</b></span><span><I.MapPin/><small>المنطقة</small><b>{request.location}</b></span><span><I.CalendarClock/><small>أُرسل</small><b>{request.createdAt}</b></span></div>{trader?<><div className="assignedDetail"><div><span className="traderAvatar">{trader.initial}</span><div><small>التاجر المكلّف من المالك</small><b>{trader.name} <I.BadgeCheck/></b><p>{trader.specialty} · <Stars rating={trader.rating}/> · {number(trader.reviews)} تقييم</p></div></div><button className="primary" onClick={()=>go('/chat?trader='+trader.id)}><I.MessageCircle/> ابدأ المحادثة</button></div>{offer?<div className="priceOfferBox"><span><I.Banknote/></span><div><small>عرض شراء التاجر</small><b>{number(offer.amount)} ج.م <em>/ {offer.unit}</em></b><p>{offer.note||'لا توجد ملاحظات إضافية.'}</p></div><time>{offer.updatedAt}</time></div>:<div className="awaitingOffer"><I.BadgeDollarSign/><span>التاجر لم يضف سعر الشراء بعد</span></div>}{canViewContact&&<div className="contactAccess"><div className="contactAccessHead"><I.ContactRound/><div><b>بيانات الاستلام الخاصة</b><small>مرئية للتاجر المُسند ومالك الموقع فقط</small></div></div><p><I.Phone/> <b>الهاتف:</b> {request.phone||'غير متاح'}</p><p><I.MapPinned/> <b>العنوان:</b> {request.address||request.location}</p><p><I.Clock3/> <b>وقت مناسب للتواصل:</b> {request.pickupTime||'يُنسّق عبر المحادثة'}</p></div>}</>:<div className="reviewNotice"><I.ClipboardClock/><div><b>طلبك ما زال لدى المالك</b><p>سيظهر التاجر ويفتح التواصل فور اعتماد الطلب وإسناده.</p></div></div>}</div></div></section>}

function Sell({go,createRequest}){const[files,setFiles]=useState([]);const[done,setDone]=useState('');const submit=e=>{e.preventDefault();const form=new FormData(e.currentTarget);const category=form.get('category');const image=cats.find(c=>c[0]===category)?.[3]||products[0].img;const id=createRequest({title:form.get('title'),category,quantity:`${form.get('quantity')} ${form.get('unit')}`,location:form.get('location'),description:form.get('description'),phone:form.get('phone'),address:form.get('address'),pickupTime:form.get('pickupTime'),image});setDone(id)};if(done)return <section className="success saleSuccess"><span><I.Send/></span><h1>وصل طلب البيع إلى المالك</h1><p>رقم طلبك <b>#{done}</b>. ستتم مراجعته أولًا، ثم يختار مالك الموقع التاجر الأنسب حسب النوع والمنطقة والتقييم.</p><div className="successPath"><span><I.ClipboardCheck/> مراجعة المالك</span><I.ArrowLeft/><span><I.UserRoundCog/> إسناد لتاجر</span><I.ArrowLeft/><span><I.MessageCircle/> محادثة آمنة</span></div><button className="primary" onClick={()=>go('/orders')}>متابعة طلبات البيع</button></section>;return <section className="wrap page narrow sellPage"><div className="pageHead"><div><small>خطوتك الأولى للبيع</small><h1>أرسل طلب بيع</h1><p>لن يُنشر الطلب ولن يصل إلى أي تاجر قبل موافقة مالك الموقع.</p></div><span className="secureBadge"><I.ShieldCheck/> مراجعة قبل الإسناد</span></div><div className="ownerGate"><span><I.Crown/></span><div><b>بوابة موافقة المالك</b><p>يراجع المالك بيانات الطلب، ثم يُحيله بنفسه إلى تاجر متخصص. لا تختار تاجرًا ولا تبدأ عملية بيع مباشرة من هذه الصفحة.</p></div></div><form className="formCard sellform" onSubmit={submit}><label className="upload"><I.ImagePlus/><b>أضف صور الكراكيب</b><span>حتى ٨ صور بصيغة JPG أو PNG</span><input type="file" accept="image/png,image/jpeg" multiple onChange={e=>setFiles([...e.target.files].slice(0,8))}/></label>{files.length>0&&<div className="previews">{files.map((file,i)=><span key={file.name+i}><I.Image/>{file.name}<small>{i===0?'صورة رئيسية':''}</small></span>)}</div>}<div className="formgrid"><label>ماذا تريد أن تبيع؟ <i>مطلوب</i><input name="title" required placeholder="مثال: خردة نحاس نظيف"/></label><label>التصنيف <i>مطلوب</i><select name="category" required>{cats.map(c=><option key={c[0]}>{c[0]}</option>)}</select></label><label>الكمية <i>مطلوب</i><input name="quantity" required type="number" min="1" placeholder="0"/></label><label>الوحدة <i>مطلوب</i><select name="unit"><option>كجم</option><option>قطعة</option><option>مجموعة</option><option>طن</option></select></label><label className="wide">وصف الحالة <i>مطلوب</i><textarea name="description" required placeholder="اكتب الحالة وأي تفاصيل تساعد المالك على اختيار التاجر المناسب"/></label><label>رقم الهاتف للتواصل <i>مطلوب</i><input name="phone" required type="tel" inputMode="tel" placeholder="01xxxxxxxxx"/></label><label>المنطقة والمحافظة <i>مطلوب</i><input name="location" required placeholder="مثال: مدينة نصر، القاهرة"/></label><label className="wide">العنوان التفصيلي للاستلام <i>مطلوب</i><textarea name="address" required placeholder="اسم الشارع، رقم المبنى، الدور، وأقرب علامة مميزة"/></label><label className="wide">الوقت الأنسب للتواصل أو الاستلام <i>مطلوب</i><input name="pickupTime" required placeholder="مثال: يوميًا من ٤ م إلى ٨ م"/></label></div><div className="privateContactNote"><I.LockKeyhole/><span><b>بيانات التواصل والعنوان خاصة.</b> لا تظهر للعامة أو للتجار غير المكلّفين؛ يراها مالك الموقع والتاجر الذي يسند إليه الطلب فقط.</span></div><label className="privacyCheck"><input required type="checkbox"/> أؤكد أن البيانات صحيحة، وأوافق على مراجعة مالك الموقع للطلب قبل إحالته إلى أي تاجر.</label><button className="primary submit">إرسال للمراجعة <I.Send/></button></form></section>}

function SaleRequests({go,requests,traders,priceOffers}){return <section className="wrap page narrow"><div className="pageHead"><div><small>بيعك تحت المتابعة</small><h1>طلبات البيع</h1><p>تتابع حالة الموافقة والإسناد وعرض شراء التاجر هنا.</p></div><button className="primary" onClick={()=>go('/sell')}><I.Plus/> طلب بيع جديد</button></div><div className="privacyStrip"><I.EyeOff/><span>خصوصيتك محفوظة: لا تظهر بيانات التواصل والعنوان إلا للمالك والتاجر الذي يُسند إليه الطلب.</span></div><div className="saleRequestList">{requests.map(r=>{const trader=traders.find(t=>t.id===r.traderId);const offer=priceOffers.find(o=>o.requestId===r.id&&o.traderId===r.traderId);return <article key={r.id}><img src={r.image||products[0].img} alt=""/><div className="saleReqMain"><small>{r.id} · {r.createdAt}</small><h3>{r.title}</h3><p><I.Scale/> {r.quantity} · <I.MapPin/> {r.location}</p>{offer&&<span className="inlineOffer"><I.Banknote/> عرض التاجر: {number(offer.amount)} ج.م / {offer.unit}</span>}</div><Status value={r.status}/><div className="saleReqTrader">{trader?<><span className="mini">{trader.initial}</span><span><small>التاجر المُسند</small><b>{trader.name}</b></span></>:<span className="unassigned"><I.ClipboardClock/> ينتظر قرار المالك</span>}</div><button onClick={()=>go('/request/'+r.id)}>التفاصيل <I.ChevronLeft/></button></article>})}</div></section>}

function Traders({go,traders,rateTrader}){const[query,setQuery]=useState('');const[target,setTarget]=useState(null);const list=traders.filter(t=>t.status==='active').filter(t=>!query||t.name.includes(query)||t.specialty.includes(query)||t.city.includes(query));return <section className="wrap page"><div className="pageHead"><div><small>مراجَعون من مالك المنصة</small><h1>دليل التجار الموثوقين</h1><p>اطّلع على تخصص كل تاجر وتقييم عملائه. التواصل يُفعّل بعد أن يسند المالك الطلب.</p></div><button className="secondary" onClick={()=>go('/register')}><I.UserPlus/> سجّل كتاجر</button></div><div className="traderSearch"><I.Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="ابحث باسم التاجر أو تخصصه أو منطقته"/></div><div className="traderGrid directory">{list.map(t=><article className="traderCard" key={t.id}><div className="traderTop"><span className="traderAvatar">{t.initial}</span><div><h3>{t.name}{t.verified&&<I.BadgeCheck/>}</h3><p><I.MapPin/> {t.city}</p></div><StatusTrader value={t.status}/></div><div className="traderFacts"><span><I.BriefcaseBusiness/><small>التخصص</small><b>{t.specialty}</b></span><span><I.Star/><small>التقييم</small><b>{t.reviews?`${Number(t.rating).toFixed(1)} / ٥`:'جديد'}</b></span><span><I.MessageCircle/><small>الاستجابة</small><b>{t.reply}</b></span></div><div className="traderCardFoot"><span className="ratingCount"><Stars rating={t.rating}/>{number(t.reviews)} تقييم</span><div><button className="rateBtn" onClick={()=>setTarget(t)}><I.Star/> قيّم</button><button onClick={()=>go('/sell')}><I.Route/> اطلب إحالة</button></div></div></article>)}</div>{!list.length&&<Empty go={go}/>} {target&&<RatingDialog trader={target} close={()=>setTarget(null)} submit={rating=>{rateTrader(target.id,rating);setTarget(null)}}/>}</section>}
function RatingDialog({trader,close,submit}){const[rating,setRating]=useState(5);const[text,setText]=useState('');return <div className="modalBackdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><form className="ratingModal" onSubmit={e=>{e.preventDefault();submit(rating)}}><button type="button" className="modalClose" onClick={close}><I.X/></button><span className="traderAvatar large">{trader.initial}</span><h2>قيّم {trader.name}</h2><p>يساعد تقييمك العملاء والمالك في اختيار التاجر الأفضل.</p><div className="starPicker" role="radiogroup">{[1,2,3,4,5].map(n=><button type="button" key={n} aria-label={`${n} نجوم`} className={n<=rating?'selected':''} onClick={()=>setRating(n)}><I.Star fill="currentColor"/></button>)}</div><b>{rating} من ٥</b><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="ملاحظة اختيارية عن التجربة"/><button className="primary">حفظ التقييم <I.Check/></button></form></div>}

function Chat({go,traders}){const{search}=useLocation();const requested=new URLSearchParams(search).get('trader');const active=traders.filter(t=>t.status==='active');const[selected,setSelected]=useState(()=>active.find(t=>t.id===requested)?.id||active[0]?.id);const[msg,setMsg]=useState('');const[messages,setMessages]=useState({
  'tr-1':[{body:'مرحبًا، تم إسناد طلبك لي من مالك كوكب كراكيب.',mine:false,time:'١٠:٣٠'},{body:'شكرًا، هل يمكن الاتفاق على موعد المعاينة؟',mine:true,time:'١٠:٣٢'}],
  'tr-2':[{body:'أهلًا، أنا جاهز لمتابعة طلب الكرتون المُحال إليّ.',mine:false,time:'أمس'}]
});useEffect(()=>{if(requested&&active.some(t=>t.id===requested))setSelected(requested)},[requested,traders]);const trader=active.find(t=>t.id===selected)||active[0];if(!trader)return <section className="wrap page"><Empty go={go}/></section>;const list=messages[trader.id]||[];const send=e=>{e.preventDefault();if(!msg.trim())return;setMessages(prev=>({...prev,[trader.id]:[...(prev[trader.id]||[]),{body:msg,mine:true,time:'الآن'}]}));setMsg('')};return <section className="wrap page chatPage"><div className="chatNotice"><I.ShieldCheck/><span><b>محادثة مرتبطة بإسناد المالك</b> — تستخدم لتنسيق المعاينة والعرض بعد توجيه الطلب إلى التاجر، وليست لبدء بيع مباشر.</span></div><div className="chat"><aside><div className="chatAsideHead"><h1>المحادثات</h1><span>{active.length} تجار</span></div>{active.map(t=><button className={t.id===trader.id?'active':''} onClick={()=>setSelected(t.id)} key={t.id}><span className="avatar">{t.initial}</span><div><b>{t.name}</b><small><Stars rating={t.rating}/> · {t.reply}</small></div>{t.id==='tr-1'&&<time>١٠:٣٢</time>}</button>)}</aside><div className="chatbox"><div className="chathead"><span className="avatar">{trader.initial}</span><div><b>{trader.name} {trader.verified&&<I.BadgeCheck/>}</b><small><Stars rating={trader.rating}/> · {number(trader.reviews)} تقييم · {trader.specialty}</small></div><button aria-label="عرض التاجر" onClick={()=>go('/traders')}><I.Info/></button></div><div className="messages">{list.map((message,i)=><p key={i} className={message.mine?'me':'them'}>{message.body}<small>{message.time}</small></p>)}</div><form onSubmit={send}><button type="button" aria-label="إرفاق"><I.Paperclip/></button><input value={msg} onChange={e=>setMsg(e.target.value)} placeholder="اكتب رسالتك للتاجر..."/><button aria-label="إرسال"><I.Send/></button></form></div></div></section>}

function Registration({go,register,requestNotificationPermission}){const[role,setRole]=useState('client');const[done,setDone]=useState(false);const submit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));register({role,data});requestNotificationPermission();setDone(true)};if(done)return <section className="success registrationSuccess"><span>{role==='client'?<I.UserCheck/>:<I.Store/>}</span><h1>{role==='client'?'أهلًا بك في كوكب كراكيب':'تم استلام تسجيل التاجر'}</h1><p>{role==='client'?'تمت إضافتك إلى عداد العملاء فقط، ولا يُعرض اسمك أو أي بيانات تخصك في المنصة.':'أُضيف طلبك إلى قائمة التجار لدى المالك؛ ستتلقى التفعيل بعد المراجعة.'}</p><button className="primary" onClick={()=>go(role==='client'?'/sell':'/trader-login')}>{role==='client'?'أرسل أول طلب بيع':'دخول بوابة التاجر'} <I.ArrowLeft/></button></section>;return <section className="wrap page registrationPage"><div className="registrationIntro"><span className="eyebrow"><I.UserPlus/> تسجيل خارجي للمنصة</span><h1>سجّل بالطريقة التي تناسبك</h1><p>اختر عميلًا لإرسال طلبات البيع بخصوصية، أو تاجرًا لتقديم خدماتك والحصول على اعتماد مالك الموقع.</p><div className="registerBenefits"><span><I.EyeOff/> خصوصية العميل</span><span><I.ClipboardCheck/> مراجعة التجار</span><span><I.Star/> تقييمات موثوقة</span></div></div><form className="formCard registrationCard" onSubmit={submit}><div className="roleTabs"><button type="button" className={role==='client'?'selected':''} onClick={()=>setRole('client')}><span><I.UserRound/></span><b>عميل</b><small>أبيع كراكيبي</small></button><button type="button" className={role==='trader'?'selected':''} onClick={()=>setRole('trader')}><span><I.Store/></span><b>تاجر</b><small>أستقبل طلبات مُسندة</small></button></div>{role==='client'?<div className="roleExplanation clientRole"><span><I.EyeOff/></span><div><h2>تسجيل العميل بخصوصية</h2><p>يُحدَّث عداد العملاء فقط. لا يظهر اسمك أو رقمك أو أي معلومة شخصية في صفحات الموقع أو قائمة المالك العامة.</p></div></div>:<div className="roleExplanation traderRole"><span><I.BadgeCheck/></span><div><h2>تسجيل تاجر تحت المراجعة</h2><p>سيظهر طلبك في سجل التجار الخاص بمالك الموقع. بعد الاعتماد فقط يمكن إسناد طلبات البيع إليك.</p></div></div>}<div className="formgrid">{role==='client'?<><label>المحافظة <i>اختياري</i><select name="city"><option>القاهرة</option><option>الجيزة</option><option>الإسكندرية</option><option>محافظة أخرى</option></select></label><label>اهتمامك الأساسي <i>اختياري</i><select name="interest"><option>بيع كراكيب متنوعة</option><option>مواد قابلة للتدوير</option><option>أجهزة ومعدات</option></select></label></>:<><label>اسم التاجر أو المنشأة <i>مطلوب</i><input name="name" required placeholder="الاسم الظاهر في الدليل"/></label><label>التخصص <i>مطلوب</i><select name="specialty" required>{cats.map(c=><option key={c[0]}>{c[0]}</option>)}</select></label><label>المدينة أو المنطقة <i>مطلوب</i><input name="city" required placeholder="مثال: المعادي، القاهرة"/></label><label>رقم التواصل للمالك <i>مطلوب</i><input name="phone" required type="tel" placeholder="01xxxxxxxxx"/></label><label className="wide">نبذة عن الخبرة <i>اختياري</i><textarea name="about" placeholder="اذكر المواد التي تتعامل بها وخبرتك فيها"/></label></>}</div><label className="privacyCheck"><input required type="checkbox"/> {role==='client'?'أفهم أن التسجيل لا يعرض أي بياناتي الشخصية للعامة.':'أوافق على مراجعة بياناتي من مالك الموقع قبل اعتماد حساب التاجر.'}</label><button className="primary submit">{role==='client'?'تسجيل كعميل':'إرسال تسجيل التاجر'} <I.ArrowLeft/></button></form></section>}

function TraderAccess({go,traders,currentUser,setCurrentUser,requests,priceOffers,traderPrices,savePriceOffer,saveTraderPrice,requestNotificationPermission}){const[choice,setChoice]=useState(currentUser?.traderId||traders[0]?.id||'');const trader=traders.find(t=>t.id===currentUser?.traderId);if(currentUser?.role==='trader'&&trader)return <TraderDashboard go={go} trader={trader} requests={requests} priceOffers={priceOffers} traderPrices={traderPrices} savePriceOffer={savePriceOffer} saveTraderPrice={saveTraderPrice} requestNotificationPermission={requestNotificationPermission} logout={()=>setCurrentUser(null)}/>;const login=e=>{e.preventDefault();if(!choice)return;setCurrentUser({role:'trader',traderId:choice});requestNotificationPermission()};return <section className="wrap page traderLoginPage"><div className="traderLoginIntro"><span className="eyebrow"><I.Store/> مساحة التاجر</span><h1>متجرك المصغّر<br/>في كوكب كراكيب</h1><p>اعرض قائمة أسعارك، عدّلها متى شئت، واستقبل طلبات البيع التي أحالها إليك مالك الموقع لتقديم عروض شراء واضحة.</p><div className="traderLoginFeatures"><span><I.Tags/> إدارة الأسعار</span><span><I.BadgeDollarSign/> عروض شراء</span><span><I.BellRing/> تنبيهات فورية</span></div></div><form className="formCard traderLoginCard" onSubmit={login}><span className="modalIcon"><I.LogIn/></span><small>دخول التاجر</small><h2>ادخل إلى متجرك</h2><p>اختر حساب التاجر في نسخة العرض. في الإنتاج يتم ربط هذا النموذج بحساب موثّق.</p><label>حساب التاجر<select value={choice} onChange={e=>setChoice(e.target.value)}>{traders.map(t=><option value={t.id} key={t.id}>{t.name} — {t.status==='active'?'موثّق':'بانتظار الاعتماد'}</option>)}</select></label><button className="primary submit">دخول متجر التاجر <I.ArrowLeft/></button><button type="button" className="textLink" onClick={()=>go('/register')}>ليس لديك حساب؟ سجّل كتاجر</button></form></section>}
function TraderDashboard({go,trader,requests,priceOffers,traderPrices,savePriceOffer,saveTraderPrice,requestNotificationPermission,logout}){const[editing,setEditing]=useState(null);const assigned=requests.filter(r=>r.traderId===trader.id);const prices=traderPrices.filter(p=>p.traderId===trader.id);const submitPrice=e=>{e.preventDefault();const form=new FormData(e.currentTarget);saveTraderPrice({id:editing?.id,traderId:trader.id,name:form.get('name'),category:form.get('category'),amount:Number(form.get('amount')),unit:form.get('unit')});setEditing(null);e.currentTarget.reset()};if(trader.status!=='active')return <section className="wrap page narrow traderPending"><div className="pendingStoreCard"><span><I.Store/></span><h1>متجرك بانتظار اعتماد المالك</h1><p>يمكنك الدخول إلى البوابة، لكن إضافة الأسعار أو استقبال طلبات البيع يتاحان بعد أن يعتمد مالك الموقع حسابك.</p><StatusTrader value={trader.status}/><button className="secondary" onClick={logout}>تسجيل الخروج</button></div></section>;return <section className="wrap page traderDashboard"><div className="traderStoreHero"><div><span className="traderAvatar large">{trader.initial}</span><div><small>متجر تاجر موثّق</small><h1>{trader.name} <I.BadgeCheck/></h1><p><I.MapPin/> {trader.city} · <I.BriefcaseBusiness/> {trader.specialty} · <Stars rating={trader.rating}/></p></div></div><div className="storeActions"><button className="secondary" onClick={requestNotificationPermission}><I.BellRing/> تفعيل الإشعارات</button><button className="secondary" onClick={logout}><I.LogOut/> خروج</button></div></div><div className="storeKpis"><span><I.ClipboardList/><small>طلبات مُسندة</small><b>{number(assigned.length)}</b></span><span><I.Tags/><small>أسعار منشورة</small><b>{number(prices.length)}</b></span><span><I.BadgeDollarSign/><small>عروض شراء وضعتها</small><b>{number(priceOffers.filter(o=>o.traderId===trader.id).length)}</b></span><span><I.Star/><small>تقييم المتجر</small><b>{Number(trader.rating).toFixed(1)}</b></span></div><section className="storeSection"><div className="adminSectionHead"><div><small>مهمات يحددها مالك الموقع</small><h2>طلبات البيع المُسندة إليك</h2><p>أضف أو عدّل عرض الشراء الخاص بك؛ سيصل إشعار للعميل والمالك فور الحفظ.</p></div></div>{assigned.length?<div className="traderAssignments">{assigned.map(request=>{const offer=priceOffers.find(o=>o.requestId===request.id&&o.traderId===trader.id);return <article key={request.id}><img src={request.image||products[0].img} alt=""/><div className="traderAssignmentInfo"><span>{request.id} · {request.category}</span><h3>{request.title}</h3><p><I.Scale/> {request.quantity} · <I.MapPin/> {request.location}</p><div className="merchantContact"><I.LockKeyhole/><span><b>بيانات الاستلام الخاصة:</b> {request.phone} · {request.address}</span></div><button className="textLink" onClick={()=>go('/request/'+request.id)}>عرض تفاصيل العميل والطلب <I.ArrowLeft/></button></div><form className="offerEditor" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);savePriceOffer({requestId:request.id,traderId:trader.id,amount:Number(f.get('amount')),unit:f.get('unit'),note:f.get('note')})}}><span><I.Banknote/> {offer?'تعديل عرض الشراء':'أضف عرض شراء'}</span><label>السعر<input name="amount" required min="0" type="number" defaultValue={offer?.amount??''} placeholder="0"/></label><label>لكل<select name="unit" defaultValue={offer?.unit||'كجم'}><option>كجم</option><option>قطعة</option><option>مجموعة</option><option>طن</option></select></label><textarea name="note" defaultValue={offer?.note||''} placeholder="ملاحظة للعميل عن السعر أو الاستلام"/><button className="primary">{offer?'حفظ التعديل':'إرسال عرض الشراء'} <I.Send/></button>{offer&&<small>آخر تحديث: {offer.updatedAt}</small>}</form></article>})}</div>:<div className="queueEmpty"><I.ClipboardCheck/><div><b>لا توجد طلبات مسندة حاليًا</b><p>سيصلك إشعار فور أن يوجه مالك الموقع طلب بيع إلى متجرك.</p></div></div>}</section><section className="storeSection priceListSection"><div className="adminSectionHead"><div><small>واجهة متجرك العامة</small><h2>قائمة أسعار المتجر</h2><p>أضف أسعارك الإرشادية وعدّلها متى شئت. يبقى عرض الشراء النهائي مرتبطًا بكل طلب مُسند.</p></div><button className="primary" onClick={()=>setEditing({name:'',category:trader.specialty,amount:'',unit:'كجم'})}><I.Plus/> إضافة سعر</button></div><div className="merchantPriceGrid">{prices.map(price=><article key={price.id}><span><I.Tags/></span><div><small>{price.category}</small><b>{price.name}</b><p>{number(price.amount)} ج.م <em>/ {price.unit}</em></p></div><button onClick={()=>setEditing(price)}><I.Pencil/> تعديل</button></article>)}{!prices.length&&<div className="emptyPrices"><I.Tags/><span>لم تضف أسعارًا بعد.</span></div>}</div>{editing&&<div className="inlinePriceEditor"><div><b>{editing.id?'تعديل سعر في المتجر':'إضافة سعر جديد'}</b><button onClick={()=>setEditing(null)}><I.X/></button></div><form onSubmit={submitPrice}><input name="name" required defaultValue={editing.name} placeholder="اسم المادة أو الخدمة"/><select name="category" defaultValue={editing.category}>{cats.map(c=><option key={c[0]}>{c[0]}</option>)}</select><input name="amount" type="number" min="0" required defaultValue={editing.amount} placeholder="السعر بالجنيه"/><select name="unit" defaultValue={editing.unit}><option>كجم</option><option>قطعة</option><option>مجموعة</option><option>طن</option></select><button className="primary">حفظ السعر <I.Save/></button></form></div>}</section></section>}
function NotificationsPage({go,notifications,audience,markAllRead,requestNotificationPermission}){const label={owner:'مالك الموقع',client:'العميل',trader:'التاجر'}[audience]||'الحساب';const icons={request:I.ClipboardClock,approved:I.CircleCheck,assignment:I.Route,price:I.BadgeDollarSign,trader:I.Store,client:I.UsersRound,welcome:I.Sparkles,rating:I.Star};return <section className="wrap page narrow notificationsPage"><div className="pageHead"><div><small>تنبيهات {label}</small><h1>الإشعارات</h1><p>تصل التحديثات المهمة للأطراف المعنية فور حدوثها.</p></div><div className="notificationActions"><button className="secondary" onClick={requestNotificationPermission}><I.BellRing/> تفعيل إشعارات الجهاز</button><button className="textLink" onClick={markAllRead}>تحديد الكل كمقروء</button></div></div><div className="notificationPermission"><I.BellRing/><div><b>لا تفوّت أي تحديث</b><p>اسمح بإشعارات الجهاز لتعرف فورًا بوجود طلب جديد أو موافقة أو عرض سعر.</p></div><button onClick={requestNotificationPermission}>السماح</button></div><div className="notificationList">{notifications.length?notifications.map(n=>{const C=icons[n.type]||I.Bell;return <article className={n.read?'read':''} key={n.id}><span><C/></span><div><b>{n.title}</b><p>{n.body}</p><small>{n.time}</small></div>{!n.read&&<i/>}</article>}):<div className="empty"><I.BellOff/><h2>لا توجد إشعارات جديدة</h2><p>ستظهر هنا تحديثات طلبات البيع والمتجر والتقييمات.</p><button className="primary" onClick={()=>go('/')}>العودة للرئيسية</button></div>}</div></section>}

function Profile({go,clientCount,currentUser}){const role=currentUser?.role;return <section className="wrap page narrow"><div className="profileHero privacyProfile"><span className="bigavatar">{role==='trader'?<I.Store/>:<I.UserRound/>}</span><div><small>{role==='trader'?'حساب تاجر قيد الإدارة':'حساب عميل خاص'}</small><h1>{role==='trader'?'تاجر كوكب كراكيب':'عميل كوكب كراكيب'}</h1><p><I.EyeOff/> لا تظهر بياناتك في واجهة الموقع</p></div><button onClick={()=>go('/register')}><I.Pencil/> تعديل نوع التسجيل</button></div><div className="profilePrivacyCard"><I.ShieldCheck/><div><b>خصوصيتك محفوظة</b><p>يوجد الآن {number(clientCount)} عميلًا مسجلًا. هذا الرقم هو المعلومة الوحيدة المعروضة عن العملاء، من دون أسماء أو بيانات تعريفية.</p></div></div><div className="profilegrid">{[[role==='trader'?I.Store:I.Send,role==='trader'?'متجري المصغّر':'طلبات البيع',role==='trader'?'إدارة الأسعار وعروض الشراء':'أرسل وتابع طلباتك',role==='trader'?'/trader':'/orders'],[I.Store,'التجار الموثوقون','تقييمات وتخصصات التجار','/traders'],[I.Bell,'الإشعارات','موافقات وطلبات وعروض أسعار','/notifications'],[I.MessageCircle,'المحادثات','تنسيق آمن بعد الإسناد','/chat'],[I.UserPlus,'تسجيل خارجي','سجّل كعميل أو تاجر','/register'],[I.Info,'عن المنصة','كيف تحمي كوكب كراكيب العملية','/about']].map(([C,title,desc,path])=><button onClick={()=>go(path)} key={title}><span><C/></span><div><b>{title}</b><small>{desc}</small></div><I.ChevronLeft/></button>)}</div></section>}

function OwnerAccess({traders,setTraders,requests,assignRequest,clientCount,addTrader,requestNotificationPermission,onLogout}){const[authenticated,setAuthenticated]=useState(sessionStorage.getItem('kawkap_owner')==='active');const[show,setShow]=useState(false);const[loading,setLoading]=useState(false);const[error,setError]=useState('');const login=e=>{e.preventDefault();setLoading(true);setError('');const form=new FormData(e.currentTarget);window.setTimeout(()=>{if(form.get('username')==='owner'&&form.get('password')==='Kawkap@2026'){sessionStorage.setItem('kawkap_owner','active');setAuthenticated(true);requestNotificationPermission()}else setError('بيانات الدخول غير صحيحة. هذه البوابة مخصصة لمالك الموقع فقط.');setLoading(false)},500)};if(authenticated)return <Admin traders={traders} setTraders={setTraders} requests={requests} assignRequest={assignRequest} clientCount={clientCount} addTrader={addTrader} onLogout={()=>{setAuthenticated(false);onLogout()}}/>;return <section className="ownerLogin"><div className="loginBrand"><Logo/><span className="privateMark"><I.LockKeyhole/> منطقة خاصة</span><div><span className="eyebrow light"><I.ShieldCheck/> وصول المالك فقط</span><h1>كل طلب بيع<br/>تحت إشرافك</h1><p>راجع طلبات العملاء، اختر التاجر المؤهل، واعتمد التجار من لوحة واحدة. لا يستطيع أي عميل أو تاجر بدء عملية خارج هذه البوابة.</p></div><div className="loginFeatures"><span><I.ClipboardCheck/><b>مراجعة الطلبات</b></span><span><I.UserRoundCog/><b>إسناد التجار</b></span><span><I.EyeOff/><b>حماية العملاء</b></span></div></div><div className="loginSide"><form className="ownerLoginForm" onSubmit={login}><span className="lockIcon"><I.Fingerprint/></span><small>بوابة الإدارة الخاصة</small><h2>دخول مالك الموقع</h2><p>أدخل بيانات الحساب المعتمدة للوصول إلى سجلات التجار وطلبات البيع.</p>{error&&<div className="loginError"><I.CircleAlert/>{error}</div>}<label>اسم المستخدم<input required name="username" autoComplete="username" placeholder="اسم مستخدم المالك"/></label><label>كلمة المرور<div className="passwordField"><input required name="password" type={show?'text':'password'} autoComplete="current-password" placeholder="كلمة المرور"/><button type="button" onClick={()=>setShow(!show)}>{show?<I.EyeOff/>:<I.Eye/>}</button></div></label><div className="loginMeta"><span><I.ShieldAlert/> محاولات الدخول مسجلة</span><span>وصول خاص فقط</span></div><button className="primary loginSubmit" disabled={loading}>{loading?<><span className="spinner"/> جاري التحقق...</>:<>دخول لوحة المالك <I.LogIn/></>}</button><div className="ownerHelp"><I.Info/><span>هذه الواجهة معروضة كتجربة. في الإنتاج يجب ربط الدخول بنظام مصادقة وصلاحيات إدارة آمن.</span></div></form></div></section>}

function Admin({traders,setTraders,requests,assignRequest,clientCount,addTrader,onLogout}){const[openAdd,setOpenAdd]=useState(false);const active=traders.filter(t=>t.status==='active');const pending=traders.filter(t=>t.status==='pending');const review=requests.filter(r=>r.status==='review');const activate=id=>setTraders(list=>list.map(t=>t.id===id?{...t,status:'active',verified:true,reply:'يرد خلال ساعة'}:t));const suspend=id=>setTraders(list=>list.map(t=>t.id===id?{...t,status:'suspended',verified:false}:t));return <section className="wrap page admin adminDashboard"><div className="pageHead"><div><small>لوحة مالك الموقع</small><h1>إدارة طلبات البيع والتجار</h1><p>أنت نقطة الاعتماد الوحيدة قبل أي تواصل أو عملية بيع.</p></div><div className="adminActions"><button className="secondary" onClick={()=>setOpenAdd(true)}><I.UserPlus/> إضافة تاجر</button><button className="logoutBtn" onClick={onLogout}><I.LogOut/> خروج آمن</button></div></div><div className="kpis ownerKpis"><article><span><I.UsersRound/></span><small>العملاء المسجلون</small><b>{number(clientCount)}</b><em>عداد فقط — بلا بيانات شخصية</em></article><article><span><I.Store/></span><small>التجار النشطون</small><b>{number(active.length)}</b><em>{number(pending.length)} بانتظار الاعتماد</em></article><article><span><I.ClipboardClock/></span><small>طلبات تنتظر قرارك</small><b>{number(review.length)}</b><em>تحتاج مراجعة وإسناد</em></article><article><span><I.MessageCircle/></span><small>طلبات مُسندة</small><b>{number(requests.filter(r=>r.status==='assigned').length)}</b><em>بدأت مرحلة التواصل</em></article></div><div className="adminPrivacy"><span><I.EyeOff/></span><div><b>خصوصية العملاء مفعّلة</b><p>تظهر هنا إحصائية عدد العملاء فقط. لا توجد أسماء أو أرقام أو بيانات عميل في قائمة المالك أو دليل التجار.</p></div><span className="privacyCount">{number(clientCount)} عميل</span></div><OwnerRequestQueue requests={requests} traders={active} assignRequest={assignRequest}/><section className="adminSection"><div className="adminSectionHead"><div><small>سجل التجار — خاص بالمالك</small><h2>التجار المسجلون</h2><p>طلبات التجار الجدد تظهر هنا للمراجعة؛ إضافة تاجر يدويًا متاحة في هذه اللوحة فقط.</p></div><button className="primary" onClick={()=>setOpenAdd(true)}><I.Plus/> إضافة تاجر يدويًا</button></div><div className="adminTraderGrid">{traders.map(t=><TraderCard key={t.id} trader={t} admin onActivate={activate} onSuspend={suspend}/>)}</div></section>{openAdd&&<AddTrader close={()=>setOpenAdd(false)} add={data=>{addTrader(data);setOpenAdd(false)}}/>}</section>}
function OwnerRequestQueue({requests,traders,assignRequest}){const[choices,setChoices]=useState({});const awaiting=requests.filter(r=>r.status==='review');const assigned=requests.filter(r=>r.status==='assigned');return <section className="adminSection requestQueue"><div className="adminSectionHead"><div><small>لا يبدأ التواصل قبل قرارك</small><h2>طلبات البيع بانتظار الإسناد</h2><p>لا تظهر هوية العميل؛ اختر التاجر الأنسب من التجار المعتمدين ثم أحِل الطلب إليه.</p></div><span className="queueCount">{number(awaiting.length)} طلب</span></div>{awaiting.length?<div className="assignmentList">{awaiting.map(r=><article key={r.id}><img src={r.image||products[0].img} alt=""/><div className="assignmentInfo"><span>{r.id} · عميل خاص</span><h3>{r.title}</h3><p><I.BriefcaseBusiness/> {r.category} · <I.Scale/> {r.quantity} · <I.MapPin/> {r.location}</p></div><div className="assignControl"><select value={choices[r.id]||''} onChange={e=>setChoices({...choices,[r.id]:e.target.value})}><option value="">اختر تاجرًا لإسناد المهمة</option>{traders.map(t=><option value={t.id} key={t.id}>{t.name} — {t.specialty} ({Number(t.rating).toFixed(1)}★)</option>)}</select><button className="primary" onClick={()=>assignRequest(r.id,choices[r.id])}><I.Route/> اعتماد وإسناد</button></div></article>)}</div>:<div className="queueEmpty"><I.CircleCheck/><div><b>لا توجد طلبات معلّقة الآن</b><p>كل طلبات البيع تمت مراجعتها أو إسنادها إلى تاجر.</p></div></div>}<div className="assignedSummary"><b><I.Send/> آخر الطلبات المُسندة</b>{assigned.slice(0,3).map(r=>{const t=traders.find(x=>x.id===r.traderId);return <span key={r.id}>{r.id}: {r.title} <I.ArrowLeft/> {t?.name||'تاجر'}</span>})}</div></section>}
function AddTrader({close,add}){const submit=e=>{e.preventDefault();add(Object.fromEntries(new FormData(e.currentTarget)))};return <div className="modalBackdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><form className="addTraderModal" onSubmit={submit}><button type="button" className="modalClose" onClick={close}><I.X/></button><span className="modalIcon"><I.Store/></span><small>منطقة المالك الخاصة</small><h2>إضافة تاجر يدويًا</h2><p>هذا النموذج لا يظهر في التسجيل الخارجي، ويمنح التاجر اعتمادًا مباشرًا بعد الإضافة.</p><div className="formgrid"><label>اسم التاجر أو المنشأة <i>مطلوب</i><input name="name" required placeholder="مثال: مركز المستقبل للتدوير"/></label><label>التخصص <i>مطلوب</i><select name="specialty">{cats.map(c=><option key={c[0]}>{c[0]}</option>)}</select></label><label>المدينة أو المنطقة <i>مطلوب</i><input name="city" required placeholder="القاهرة، مصر"/></label><label>التقييم المبدئي<select name="rating"><option value="0">تاجر جديد — بلا تقييم</option><option value="4.5">٤٫٥</option><option value="4.8">٤٫٨</option><option value="5">٥٫٠</option></select></label></div><div className="modalActions"><button type="button" className="secondary" onClick={close}>إلغاء</button><button className="primary"><I.UserPlus/> إضافة واعتماد التاجر</button></div></form></div>}

function About(){return <section className="wrap page about"><span className="eyebrow"><I.Leaf/> مهمتنا</span><h1>عن كوكب كراكيب</h1><p className="lead">منصة منظَّمة لبيع الكراكيب والمواد القابلة لإعادة الاستخدام. العميل يرسل طلبه، ومالك الموقع يراجعه ويختار التاجر المناسب، ثم يفتح التواصل بصورة واضحة وآمنة.</p><div className="aboutgrid"><article><I.Crown/><h2>قرار المالك أولًا</h2><p>كل طلب بيع يمر بالمراجعة قبل الإسناد، ولا يتم توجيهه تلقائيًا إلى أي تاجر.</p></article><article><I.Star/><h2>تاجر يُقاس بالتجربة</h2><p>لكل تاجر تخصص وتقييمات ظاهرة تساعد على بناء ثقة حقيقية بعد كل تعامل.</p></article><article><I.EyeOff/><h2>عميل ببيانات محمية</h2><p>نكتفي بعدّ العملاء المسجلين في الواجهة؛ لا نعرض أسماءهم أو بياناتهم الخاصة.</p></article></div></section>}

createRoot(document.getElementById('root')).render(<BrowserRouter><App/></BrowserRouter>);
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js'));
